mapper.update:
UPDATE asset_binding_attempt SET status=#{status}, updated_at=CURRENT_TIMESTAMP(6)
WHERE request_id=#{attempt.requestId} AND owner_id=#{attempt.ownerId}
  AND asset_id=#{attempt.assetId} AND purpose=#{attempt.purpose} AND status='OPEN'

mapper.select:
SELECT * FROM asset_binding_attempt WHERE status='OPEN'

  AND (created_at > #{cursor.createdAt} OR (created_at=#{cursor.createdAt} AND request_id > #{cursor.requestId}))

ORDER BY created_at, request_id LIMIT #{limit}
